"""The ordered gate-segment registry. Row order IS the legacy execution order - the whole contract of feature 022."""

# CLAUSE-13 JUSTIFICATION (constitution Principle X): this file exceeds the ~1,000-line
# file threshold DELIBERATELY. GATE_SEGMENTS is ordered DATA, not logic - its row order is
# the execution contract (feature 022), and splitting the tuple across files would make
# that order un-auditable for zero token benefit: nobody reads the registry linearly, and
# gate(M, only=...) is how a row is found in practice.

